/// <summary>
/// Retrieve records inside AVADAIReportExportWork table
/// </summary>
/// <param name = "AVADAIReportExportTable">AVADAIReportExportTable</param>
/// <param name = "boolean">update table </param>
/// <param name = "UserConnection">user connection value </param>
/// <returns> <c>AVADAIReportExportWork</c> object.</returns>
public static AVADAIReportExportWork find(
    AVADAIReportExportTable _reportExportTable,
    boolean _forUpdate = false,
    UserConnection _userConnection = null)
{
    AVADAIReportExportWork reportExportWork;

    if (_reportExportTable)
    {
        reportExportWork.selectForUpdate(_forUpdate);
        if (_userConnection)
        {
            reportExportWork.setConnection(_userConnection);
        }

        select firstonly reportExportWork
            where reportExportWork.ReportExportTable == _reportExportTable.RecId;
    }

    return reportExportWork;

}

/// <summary>
/// Check for record existence
/// </summary>
/// <param name = "RefRecId">RefRecid.</param>
/// <returns>A <c>boolean</c> object.</returns>
public static boolean exist(RefRecId     _reportExportTable )
{
    boolean                     found;
    AVADAIReportExportWork      aVADAIReportExportWork;

    if(_reportExportTable)
    {
        found = (select firstonly RecId from aVADAIReportExportWork where aVADAIReportExportWork.ReportExportTable == _reportExportTable).RecId != 0;
    }

    return found;
}

/// <summary>
/// Set form configuration.
/// </summary>
/// <param name = "AVADAIArchiveFormConfig">The configuration.</param>
/// <returns>A <c>AVADAIArchiveFormConfig</c> object.</returns>
public static AVADAIReportExportWork findOrCreate(  AVADAIReportExportTable     _reportExportTable, 
                                                    boolean                     _forUpdate = false,
                                                    UserConnection              _userConnection = null)
{
    #OCCRetryCount
    AVADAIReportExportWork reportExportWork, newReportExportWork;

    if (!_reportExportTable)
    {
        throw error(strFmt("@SYS89866", fieldPName(AVADAIReportExportTable, ExecutionId)));
    }

    try
    {
        reportExportWork = AVADAIReportExportWork::find(_reportExportTable, _forUpdate, _userConnection);

        if (!reportExportWork.RecId)
        {
            if (_userConnection)
            {
                newReportExportWork.setConnection(_userConnection);
            }
            newReportExportWork.clear();
            newReportExportWork.ReportExportTable = _reportExportTable.RecId;
            newReportExportWork.insert();

            reportExportWork.selectForUpdate(_forUpdate);
            if (_userConnection)
            {
                reportExportWork.setConnection(_userConnection);
            }
            select firstonly reportExportWork
                where reportExportWork.RecId == newReportExportWork.RecId;
        }
    }
    catch (Exception::DuplicateKeyException)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::DuplicateKeyExceptionNotRecovered;
        }
        else
        {
            retry;
        }
    }

    return reportExportWork;
}
